import 'package:flutter/material.dart';
import 'package:webview_flutter/webview_flutter.dart';

class BasicWebViewScreen extends StatefulWidget {
  const BasicWebViewScreen({super.key});

  @override
  State<BasicWebViewScreen> createState() => _BasicWebViewScreenState();
}

class _BasicWebViewScreenState extends State<BasicWebViewScreen> {
  late final WebViewController _controller;
  bool _isLoading = true;
  int _loadingProgress = 0;

  @override
  void initState() {
    super.initState();
    _controller = WebViewController()
      ..setJavaScriptMode(JavaScriptMode.unrestricted)
      ..setBackgroundColor(Colors.white)
      ..setNavigationDelegate(
        NavigationDelegate(
          onProgress: (progress) {
            setState(() => _loadingProgress = progress);
          },
          onPageStarted: (url) {
            setState(() => _isLoading = true);
          },
          onPageFinished: (url) {
            setState(() => _isLoading = false);
          },
          onWebResourceError: (error) {
            debugPrint('WebView error: ${error.description}');
          },
        ),
      )
      ..loadRequest(Uri.parse('https://flutter.dev'));
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('WebView'),
        bottom: _isLoading
            ? PreferredSize(
                preferredSize: const Size.fromHeight(2),
                child: LinearProgressIndicator(
                  value: _loadingProgress / 100,
                ),
              )
            : null,
      ),
      body: WebViewWidget(controller: _controller),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:webview_flutter/webview_flutter.dart';

class NavigationWebViewScreen extends StatefulWidget {
  const NavigationWebViewScreen({super.key});

  @override
  State<NavigationWebViewScreen> createState() => _NavigationWebViewScreenState();
}

class _NavigationWebViewScreenState extends State<NavigationWebViewScreen> {
  late final WebViewController _controller;
  String _currentUrl = '';
  bool _canGoBack = false;
  bool _canGoForward = false;

  @override
  void initState() {
    super.initState();
    _controller = WebViewController()
      ..setJavaScriptMode(JavaScriptMode.unrestricted)
      ..setNavigationDelegate(
        NavigationDelegate(
          onPageFinished: (url) async {
            _currentUrl = url;
            _canGoBack = await _controller.canGoBack();
            _canGoForward = await _controller.canGoForward();
            setState(() {});
          },
          onNavigationRequest: (request) {
            // 특정 URL 차단
            if (request.url.contains('ads')) {
              return NavigationDecision.prevent;
            }
            // 외부 앱으로 열기 (예: tel:, mailto:)
            if (!request.url.startsWith('http')) {
              // url_launcher로 처리
              return NavigationDecision.prevent;
            }
            return NavigationDecision.navigate;
          },
        ),
      )
      ..loadRequest(Uri.parse('https://flutter.dev'));
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: Text(
          _currentUrl.isEmpty ? 'WebView' : Uri.parse(_currentUrl).host,
          style: const TextStyle(fontSize: 14),
        ),
        actions: [
          IconButton(
            icon: const Icon(Icons.refresh),
            onPressed: () => _controller.reload(),
          ),
        ],
      ),
      body: Column(
        children: [
          Expanded(
            child: WebViewWidget(controller: _controller),
          ),
          // 네비게이션 바
          Container(
            color: Colors.grey[200],
            child: SafeArea(
              child: Row(
                mainAxisAlignment: MainAxisAlignment.spaceEvenly,
                children: [
                  IconButton(
                    icon: const Icon(Icons.arrow_back),
                    onPressed: _canGoBack
                        ? () => _controller.goBack()
                        : null,
                  ),
                  IconButton(
                    icon: const Icon(Icons.arrow_forward),
                    onPressed: _canGoForward
                        ? () => _controller.goForward()
                        : null,
                  ),
                  IconButton(
                    icon: const Icon(Icons.home),
                    onPressed: () {
                      _controller.loadRequest(
                        Uri.parse('https://flutter.dev'),
                      );
                    },
                  ),
                  IconButton(
                    icon: const Icon(Icons.share),
                    onPressed: () {
                      // share_plus로 URL 공유
                    },
                  ),
                ],
              ),
            ),
          ),
        ],
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:webview_flutter/webview_flutter.dart';

class JavaScriptWebViewScreen extends StatefulWidget {
  const JavaScriptWebViewScreen({super.key});

  @override
  State<JavaScriptWebViewScreen> createState() => _JavaScriptWebViewScreenState();
}

class _JavaScriptWebViewScreenState extends State<JavaScriptWebViewScreen> {
  late final WebViewController _controller;
  String _result = '';

  @override
  void initState() {
    super.initState();
    _controller = WebViewController()
      ..setJavaScriptMode(JavaScriptMode.unrestricted)
      // JavaScript에서 Flutter로 메시지 보내기
      ..addJavaScriptChannel(
        'FlutterChannel',
        onMessageReceived: (message) {
          setState(() => _result = message.message);
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(content: Text('JS에서 받음: ${message.message}')),
          );
        },
      )
      ..loadHtmlString(_htmlContent);
  }

  // Flutter에서 JavaScript 실행
  Future<void> _callJavaScript() async {
    final result = await _controller.runJavaScriptReturningResult(
      'document.getElementById("result").innerText',
    );
    setState(() => _result = result.toString());
  }

  // JavaScript 함수 호출
  Future<void> _invokeJsFunction() async {
    await _controller.runJavaScript(
      'showAlert("Flutter에서 호출됨!")',
    );
  }

  // DOM 조작
  Future<void> _changeDomColor() async {
    await _controller.runJavaScript(
      'document.body.style.backgroundColor = "#f0f0f0"',
    );
  }

  static const String _htmlContent = '''
<!DOCTYPE html>
<html>
<head>
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <style>
    body { font-family: sans-serif; padding: 20px; }
    button { padding: 10px 20px; margin: 10px 0; font-size: 16px; }
    #result { padding: 20px; background: #eee; margin: 20px 0; }
  </style>
</head>
<body>
  <h2>JavaScript 통신 테스트</h2>

  <button onclick="sendToFlutter()">Flutter로 메시지 보내기</button>

  <div id="result">결과가 여기에 표시됩니다</div>

  <button onclick="updateResult()">결과 업데이트</button>

  <script>
    var counter = 0;

    function sendToFlutter() {
      FlutterChannel.postMessage('Hello from JavaScript! Count: ' + (++counter));
    }

    function updateResult() {
      document.getElementById('result').innerText = 'Updated: ' + new Date().toLocaleTimeString();
    }

    function showAlert(message) {
      document.getElementById('result').innerText = message;
    }
  </script>
</body>
</html>
''';

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('JavaScript 통신')),
      body: Column(
        children: [
          Expanded(
            child: WebViewWidget(controller: _controller),
          ),
          Container(
            padding: const EdgeInsets.all(16),
            color: Colors.grey[100],
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                Text('Flutter에서 받은 결과: $_result'),
                const SizedBox(height: 12),
                Row(
                  children: [
                    Expanded(
                      child: ElevatedButton(
                        onPressed: _callJavaScript,
                        child: const Text('JS 결과 읽기'),
                      ),
                    ),
                    const SizedBox(width: 8),
                    Expanded(
                      child: ElevatedButton(
                        onPressed: _invokeJsFunction,
                        child: const Text('JS 함수 호출'),
                      ),
                    ),
                  ],
                ),
                const SizedBox(height: 8),
                ElevatedButton(
                  onPressed: _changeDomColor,
                  child: const Text('배경색 변경'),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:webview_flutter/webview_flutter.dart';

// 약관 동의 화면
class TermsWebViewScreen extends StatefulWidget {
  final String title;
  final String url;

  const TermsWebViewScreen({
    super.key,
    required this.title,
    required this.url,
  });

  @override
  State<TermsWebViewScreen> createState() => _TermsWebViewScreenState();
}

class _TermsWebViewScreenState extends State<TermsWebViewScreen> {
  late final WebViewController _controller;
  bool _isLoading = true;
  bool _hasScrolledToBottom = false;

  @override
  void initState() {
    super.initState();
    _controller = WebViewController()
      ..setJavaScriptMode(JavaScriptMode.unrestricted)
      ..addJavaScriptChannel(
        'ScrollChannel',
        onMessageReceived: (message) {
          if (message.message == 'bottom') {
            setState(() => _hasScrolledToBottom = true);
          }
        },
      )
      ..setNavigationDelegate(
        NavigationDelegate(
          onPageFinished: (_) {
            setState(() => _isLoading = false);
            // 스크롤 감지 스크립트 주입
            _controller.runJavaScript('''
              window.addEventListener('scroll', function() {
                if ((window.innerHeight + window.scrollY) >= document.body.offsetHeight - 50) {
                  ScrollChannel.postMessage('bottom');
                }
              });
            ''');
          },
        ),
      )
      ..loadRequest(Uri.parse(widget.url));
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(widget.title)),
      body: Stack(
        children: [
          WebViewWidget(controller: _controller),
          if (_isLoading)
            const Center(child: CircularProgressIndicator()),
        ],
      ),
      bottomNavigationBar: SafeArea(
        child: Padding(
          padding: const EdgeInsets.all(16),
          child: ElevatedButton(
            onPressed: _hasScrolledToBottom
                ? () => Navigator.pop(context, true)
                : null,
            child: Text(
              _hasScrolledToBottom ? '동의하고 계속하기' : '끝까지 스크롤해주세요',
            ),
          ),
        ),
      ),
    );
  }
}

// 결제 웹뷰 (결과 URL 감지)
class PaymentWebViewScreen extends StatefulWidget {
  final String paymentUrl;
  final String successUrl;
  final String failUrl;

  const PaymentWebViewScreen({
    super.key,
    required this.paymentUrl,
    required this.successUrl,
    required this.failUrl,
  });

  @override
  State<PaymentWebViewScreen> createState() => _PaymentWebViewScreenState();
}

class _PaymentWebViewScreenState extends State<PaymentWebViewScreen> {
  late final WebViewController _controller;

  @override
  void initState() {
    super.initState();
    _controller = WebViewController()
      ..setJavaScriptMode(JavaScriptMode.unrestricted)
      ..setNavigationDelegate(
        NavigationDelegate(
          onNavigationRequest: (request) {
            final url = request.url;

            // 결제 성공
            if (url.startsWith(widget.successUrl)) {
              Navigator.pop(context, {'success': true, 'url': url});
              return NavigationDecision.prevent;
            }

            // 결제 실패
            if (url.startsWith(widget.failUrl)) {
              Navigator.pop(context, {'success': false, 'url': url});
              return NavigationDecision.prevent;
            }

            return NavigationDecision.navigate;
          },
        ),
      )
      ..loadRequest(Uri.parse(widget.paymentUrl));
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('결제'),
        leading: IconButton(
          icon: const Icon(Icons.close),
          onPressed: () => Navigator.pop(context, {'success': false}),
        ),
      ),
      body: WebViewWidget(controller: _controller),
    );
  }
}

